from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe');base='ee92da2f176d381696e33626e409f9bb4c50561b'
src=repo/'tools/ats_review_answer_matches.py';test=repo/'tests/test_ats_review_answer_matches.py';bank=repo/'tools/ats_verified_answer_bank.py'
def git(*a):return subprocess.run(['git',*a],cwd=repo,check=True,text=True,capture_output=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
if not src.exists() or not test.exists():raise SystemExit('FAILED_REQUEST_FILES_MISSING')
# Test had a literal backslash-n, not a newline. Correct test to exercise actual whitespace.
s=test.read_text()
needle=r'AI\\n in your role?'
if needle not in s:raise SystemExit('TEST_SOURCE_CHANGED')
test.write_text(s.replace(needle,'AI'+'\\n'+' in your role?'))
# Previous assertion assumed sort order for review items. Match the item by its question.
s=test.read_text()
needle='assert out["human_review"][0]["status"]=="human_review"\\n    assert out["human_review"][0]["verified_answer_available"]'
replacement='assert all(item["status"]=="human_review" for item in out["human_review"])\\n    assert next(item for item in out["human_review"] if item["question"]=="Do you use AI in your role?")["verified_answer_available"]'
if needle not in s:raise SystemExit('SORT_ORDER_ASSERTION_CHANGED')
test.write_text(s.replace(needle,replacement))
p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_ats_review_answer_matches.py','tests/test_ats_verified_answer_bank.py','tests/test_ats_review_batch.py','tests/test_ats_question_triage.py','tests/test_ats_field_labels.py','tests/test_live_ats_inspect.py'],cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
try:o,e=p.communicate(timeout=120)
except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);raise SystemExit('TEST_TIMEOUT')
print('TEST_EXIT',p.returncode,'STDOUT',o[-3500:],'STDERR',e[-1300:],flush=True)
if p.returncode:raise SystemExit('TESTS_FAILED_NO_PUSH')
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED_AFTER_TEST')
subprocess.run(['git','add','--','tools/ats_review_answer_matches.py','tests/test_ats_review_answer_matches.py','tools/ats_verified_answer_bank.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','feat: match scoped verified answers in human review without exposing values'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True)
print('VERIFIED_PUSH',git('rev-parse','HEAD'),flush=True)
